mat2 bayer2x2 = mat2(
        0.0, 2.0/4.0,
        3.0/4.0, 1.0/4.0
    );

const mat4 bayer4x4 = mat4(
        1.0 / 16.0, 9.0 / 16.0, 3.0 / 16.0, 11.0 / 16.0,
        13.0 / 16.0, 5.0 / 16.0, 15.0 / 16.0, 7.0 / 16.0,
        4.0 / 16.0, 12.0 / 16.0, 2.0 / 16.0, 10.0 / 16.0,
        16.0 / 16.0, 8.0 / 16.0, 14.0 / 16.0, 6.0 / 16.0
    );

vec3 dither2x2(vec3 in_color, vec2 fragPos)
{
    ivec2 ipos = ivec2(mod(fragPos, 2.0));

    float threshould = bayer2x2[ipos.x][ipos.y];
    vec3 col = vec3(1.0);

    if (in_color.x < threshould)
    {
        col = vec3(0.0);
    }

    return col;
}
vec3 dither4x4(vec3 in_color, vec2 fragPos)
{
    ivec2 ipos = ivec2(mod(fragPos, 4.0));
    float threshold = bayer4x4[ipos.x][ipos.y];

    vec3 col = vec3(1.0);

    if (in_color.x < threshold)
    {
        col = vec3(0.0);
    }
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy;

    vec3 color = vec3(uv.x);
    color = texture(iChannel0, uv).rgb;
    color = vec3(dot(color, vec3(0.299, 0.587, 0.114)));

    //gamma decode
    color = pow(color, vec3(2.0));

    color = dither4x4(color, fragCoord.xy);

    fragColor = vec4(color, 1.0);
}
